def text(k,l,optional=False):return dict(key=k,label=l,type='text',maxLength=160,optional=optional)
def num(k,l,maximum=1000000,integer=False):return dict(key=k,label=l,type='number',min=0,max=maximum,integer=integer,step='1' if integer else '0.01')
def date(k,l,optional=False):return dict(key=k,label=l,type='date',optional=optional)
def select(k,l,options):return dict(key=k,label=l,type='select',options=options)
C=[]
def add(slug,name,kind,category,fields,row,sample,desc,formula,example,limits,steps,related,journal,visual,top=None):
 colors=['#315445','#7c3d50','#9b4826','#225f7b','#655034','#295b63','#485489','#77513b','#66518a','#356449']
 c=dict(slug=slug,name=name,kind=kind,category=category,color=colors[len(C)],pale='#f4f3ec',description=desc,fields=[text('title','Worksheet label'),date('asOf','Review date')]+fields,rowFields=[text('ref','Unique record reference')]+row,sample={'top':dict(title='Fictional '+name.lower(),asOf='2026-10-21',**(top or {})),'rows':sample},maxRows=100,formula=formula,reportNote=formula+' '+limits,example=example,limits=limits,steps=steps,features=[desc,'Show record-level results with assumptions and review notes.','Keep editable device saves and portable backups without an account.'],workflow='Check the record reference and scope before acting. Keep the original evidence alongside this worksheet, assign a next action and review it again after the real event. A saved plan does not update any external system.',faq=[['Does this take action for me?','No. It calculates or organizes the information you enter. Decisions and updates to your real records remain manual.'],['Can I restore a CSV or PDF?','No. Use the JSON backup to restore editable fields. CSV and printed PDF are reports.']],related=related,journal=journal,visual=visual)
 C.append(c)
