add('dead-stock-review-planner','Dead Stock Review Planner','dead','inventory',[money,num('threshold','Review after inactive days',3650,True)],[text('item','SKU / location'),num('qty','On-hand units',1000000,True),num('cost','Unit cost'),date('received','First receipt date'),date('sale','Last sale date (blank if none)',True),text('action','Proposed next action')],[dict(ref='STOCK-01',item='Blue scarf / Shelf A',qty='20',cost='8',received='2026-06-01',sale='2026-07-01',action='Review merchandising before reordering')],'Review stock with no recent sales. See inactivity days and inventory cost at risk using your own review threshold.','Inactivity days = review date minus last sale date, or first receipt date if no sale is entered. Flag when days are at least the chosen threshold and quantity is positive. Value = units × entered cost.','20 scarves at $8 cost represent $160. July 1 to October 21 is 112 days; at a 90-day threshold the row needs review.','Inactivity is not proof that stock is obsolete. No sales forecast, accounting write-down or disposal decision is made. Dates must describe events on or before the review date.',['Set a review date, currency and inactivity threshold.','Enter one SKU/location per reference with first receipt and latest sale dates.','Leave last sale blank only if none has occurred.','Review flagged lines individually and record a next action.'],[['stock-coverage-planner','Compare demand-based coverage']], 'boutique-inventory-spreadsheet',['112 days inactive','20 units × $8','$160 to review'],dict(currency='USD',threshold='90'))
add('boutique-return-to-stock-log','Boutique Return to Stock Log','returns','inventory',[],[text('item','SKU / variant'),date('received','Return received date'),num('qty','Returned units',1000000,True),num('released','Inspected sellable units',1000000,True),num('rejected','Rejected units',1000000,True),text('reviewer','Reviewer / owner'),text('note','Condition or next action')],[dict(ref='RETURN-01',item='TEE-BLK-M',received='2026-10-20',qty='5',released='3',rejected='1',reviewer='Example owner',note='Inspect one remaining unit')],'Separate returned clothing into inspected sellable, rejected and pending units. Keep condition notes and a reviewer with each return.','Pending units = returned units − inspected sellable units − rejected units. Released plus rejected cannot exceed returned units.','Five returned tees with three sellable and one rejected leave one pending. Only the three sellable units are candidates for a real stock return entry.','This worksheet does not issue refunds or add stock. A refund and a physical return are separate events. Enter inspection decisions already made, not an assumed approval.',['Enter the review date and a unique return reference.','Record the exact variant and receipt date.','Enter inspected sellable and rejected quantities; pending is calculated.','Post approved stock movements once in your actual register.'],[['physical-count-adjustment-worksheet','Reconcile physical stock']], 'boutique-inventory-spreadsheet',['5 units returned','3 sellable · 1 rejected','1 pending review'])
add('seasonal-stock-clearance-planner','Seasonal Stock Clearance Planner','clearance','inventory',[money],[text('item','SKU / style'),num('qty','Units proposed for sale',1000000,True),num('price','Current unit price'),num('markdown','Markdown percent',100),num('cost','Unit inventory cost'),num('fee','Selling fee percent',100),num('fixed','Other scenario costs')],[dict(ref='CLEAR-01',item='Seasonal tote',qty='10',price='30',markdown='20',cost='12',fee='5',fixed='15')],'Compare a clearance price with inventory cost and selling fees. See a transparent sell-through scenario before choosing a markdown.','New unit price = current price × (1 − markdown/100), rounded to cents. Revenue = units × new price. Contribution = revenue − item cost − percentage selling fees − other scenario costs.','10 totes at $30 with a 20% markdown sell at $24. Revenue is $240, item cost $120, fees $12 and other costs $15, leaving $93 modeled contribution.','Assumes every entered unit sells. Contribution excludes unentered overhead, taxes, returns and shipping. It is not a prediction of sales or net profit.',['Choose one currency and a scenario label.','Enter quantity and current price for each distinct style.','Add markdown, unit cost, percentage fees and other costs.','Review negative contributions and test another scenario before changing prices.'],[['dead-stock-review-planner','Review inactive stock first']], 'boutique-inventory-spreadsheet',['$30 → $24','10 units · $240 revenue','$93 contribution'],dict(currency='USD'))
add('shipment-cost-allocation-tool','Shipment Cost Allocation Tool','allocation','inventory',[money,num('shared','Shared shipment charges'),select('basis','Allocation basis',['Merchandise value','Units'])],[text('item','SKU'),num('qty','Received units',1000000,True),num('cost','Merchandise unit cost')],[dict(ref='LINE-A',item='Notebook A',qty='10',cost='5'),dict(ref='LINE-B',item='Notebook B',qty='20',cost='5')],'Allocate shared shipment charges across received SKUs by merchandise value or units. Review landed line totals and unit-cost estimates.','Weights use merchandise value or units. Allocate shared charges in cents using largest fractional remainders; tied remainders follow row order. Landed line total = merchandise cost + allocation. Unit estimate = landed total / quantity.','With $30 shared charges and lines costing $50 and $100, value allocation gives $10 and $20. Landed totals are $60 and $120; both unit estimates are $6.','Only entered charges are allocated. This is a planning estimate, not a customs, tax or accounting valuation rule. Rounded unit estimates may not multiply back to exact line totals.',['Choose a currency, total shared charges and allocation basis.','Enter positive received quantities and merchandise unit costs.','Review how weights distribute the charges.','Keep line totals as the cent-accurate record and document the chosen basis.'],[['supplier-quote-comparison','Compare supplier quotes']], 'supplier-quote-comparison',['$30 shared charges','$10 to A · $20 to B','$6 per unit'],dict(currency='USD',shared='30',basis='Merchandise value'))
add('repair-job-handoff-planner','Repair Job Handoff Planner','handoff','operations',[],[text('machine','Machine / serial reference'),text('owner','Assigned person'),date('due','Next action date'),select('approval','Customer approval',['Pending','Recorded','Not required']),select('parts','Parts status',['Waiting','Ready','Not required']),select('status','Handoff status',['Open','Handed over']),text('action','Next action / evidence reference')],[dict(ref='JOB-01',machine='Example mower M-12',owner='Example technician',due='2026-10-20',approval='Pending',parts='Waiting',status='Open',action='Request approval before ordering the belt')],'Prepare a small-engine repair handoff with ownership, next actions, approval records and parts blockers. Review overdue open jobs.','An open job is overdue when its next action date is before the review date. Pending approval or waiting parts flags a blocker. Handed-over rows stay in the record but leave the open queue.','JOB-01 is due October 20 and reviewed October 21: one day overdue, with approval and parts still pending.','This is an administrative handoff, not a repair procedure, safety inspection or permission to release equipment. It does not contact customers or order parts.',['Give each job a unique reference and machine identifier.','Assign the next owner and action date.','Record actual approval and parts states.','Review blockers together and mark handed over only after the handoff occurs.'],[['repair-parts-labour-worksheet','Prepare a parts and labor estimate']], 'repair-shop-parts-inventory',['JOB-01 · mower','Approval + parts pending','Next owner and action'])
add('rental-dispatch-return-checklist','Rental Dispatch Return Checklist','rental','operations',[],[text('asset','Asset / kit'),date('due','Return due date'),num('out','Units dispatched',1000000,True),num('returned','Units physically returned',1000000,True),num('held','Returned units held for inspection',1000000,True),select('release','Inspection decision',['Pending','Recorded']),text('note','Condition / accessory note')],[dict(ref='HIRE-01',asset='Example lighting kit',due='2026-10-20',out='8',returned='7',held='2',release='Pending',note='One stand missing; inspect two returned lamps')],'Reconcile rental units dispatched, returned and held for inspection. Keep missing quantities and recorded inspection decisions separate.','Outstanding = dispatched − returned. Potentially releasable = returned − held, but the release candidate remains zero while inspection decision is Pending. Overdue outstanding units require a return date before the review date.','Eight units dispatched and seven returned leave one outstanding. Two returned units are held. While inspection is pending, the tool shows zero release candidates.','Counts do not establish fitness for use or customer liability. Use your approved equipment inspection procedure and actual asset records before release. No deposits or damage charges are calculated.',['Use one rental/asset reference per row.','Enter dispatch and actual return quantities.','Separate inspection holds from missing units.','Record inspection only after the responsible person completes the required checks.'],[['rental-booking-conflict-checker','Check booking overlaps']], 'rental-equipment-maintenance-log',['8 out · 7 returned','1 missing · 2 held','Inspection still pending'])
add('calibration-due-date-planner','Calibration Due Date Planner','calibration','operations',[num('window','Look-ahead days',3650,True)],[text('asset','Instrument identifier'),date('last','Last calibration date'),date('due','Approved next due date'),select('status','Record status',['Active','Out of service']),text('source','Approved schedule / certificate reference')],[dict(ref='CAL-01',asset='Example scale S-01',last='2026-04-18',due='2026-10-18',status='Active',source='Example approved schedule revision 2')],'Review instrument calibration dates against a chosen date. Separate past-due, due-today and upcoming records using your approved schedule.','Days to due = approved next due date − review date in calendar days. Past due is negative; due today is zero; upcoming is positive and within the look-ahead. Out-of-service rows are shown separately.','An active instrument due October 18 is three days past due on October 21. The worksheet does not decide whether that instrument may be used.','Enter an already approved due date. The tool does not recommend intervals, establish traceability, validate certificates or authorize equipment use.',['Set the review date and look-ahead window.','Enter an instrument and its last calibration date.','Copy the approved next due date and source reference.','Review overdue records with the responsible person and retain service evidence.'],[['equipment-maintenance-due-planner','Plan maintenance separately']], 'equipment-calibration-log',['Approved date only','October 18 → October 21','3 days past due'],dict(window='30'))
add('batch-expiry-review-planner','Batch Expiry Review Planner','expiry','operations',[num('window','Look-ahead days',3650,True)],[text('item','Item / lot'),date('expiry','Recorded expiry date'),num('qty','Units physically held',1000000,True),select('status','Stock status',['Released','Hold','Disposed']),text('action','Review owner / next action')],[dict(ref='LOT-01',item='Example craft supply lot',expiry='2026-10-25',qty='30',status='Released',action='Owner to review the recorded date and handling rules')],'Sort lot dates for review while keeping released, held and disposed records distinct. See approaching dates without treating a date as permission to use stock.','Days to recorded expiry = expiry date − review date. Before review is past date; same date requires today review; positive days within the window are approaching. Disposed records require zero held units.','A lot dated October 25 is four days away on October 21. Its 30 units stay in their entered stock status; the tool does not release them.','Expiry interpretation depends on the product, source and applicable rules. No safety, shelf-life extension, recall decision or sale authorization is provided.',['Set review date and look-ahead days.','Record the exact item/lot and date from the authoritative record.','Enter physically held units and their current status.','Review earliest dates and hold records with the responsible owner.'],[['physical-count-adjustment-worksheet','Check physical quantities']], 'batch-lot-traceability-log',['LOT-01 · 30 units','October 25 recorded date','4 days to review'],dict(window='14'))
add('executive-function-task-breakdown','Executive Function Task Breakdown','tasks','personal',[num('budget','Available work minutes',10000,True)],[text('task','One concrete next step'),text('cue','Start cue / needed material'),num('minutes','Estimated focused minutes',1440,True),select('status','Step status',['To do','Done','Blocked']),text('note','Finish signal / blocker')],[dict(ref='STEP-01',task='Gather five receipts',cue='Open the receipts envelope',minutes='10',status='To do',note='Five receipts on the desk'),dict(ref='STEP-02',task='Enter the five amounts',cue='Open the expense sheet',minutes='20',status='To do',note='Five rows recorded')],'Break a task into visible next steps, estimate remaining effort and compare unblocked work with your available time.','Remaining minutes sum all non-done steps. Ready minutes sum To do steps. Blocked minutes are reported separately. Ready time gap = max(0, ready minutes − available work minutes).','Two ready steps taking 10 and 20 minutes need 30 minutes. A 25-minute work window leaves a five-minute ready-work gap.','A planning aid, not treatment or diagnosis. Estimates do not guarantee completion. It does not choose priorities or send reminders.',['Enter a realistic focused-work window, excluding breaks.','Write one observable action per step with a start cue.','Estimate minutes and identify blocked steps.','Choose a manageable first step and update status after doing it.'],[['leave-on-time-routine-planner','Work backward from a departure time']], 'adhd-planner-for-adults',['Gather · 10 minutes','Enter · 20 minutes','25 available · 5 short'],dict(budget='25'))
add('free-trial-cancellation-calendar','Free Trial Cancellation Calendar','trials','cashflow',[num('window','Look-ahead days',3650,True)],[text('service','Trial / service'),date('end','Trial end date'),num('buffer','Chosen action buffer days',3650,True),select('status','Cancellation status',['Open','Requested','Confirmed']),text('source','Terms / confirmation reference')],[dict(ref='TRIAL-01',service='Example design app',end='2026-10-28',buffer='7',status='Open',source='Check actual account terms and cutoff time')],'Plan a manual trial-cancellation review before an entered trial end date. Track requested versus confirmed cancellation without claiming it is complete.','Action date = trial end date − chosen buffer calendar days. Requested remains active until confirmed. An action date on or before review requires attention; confirmed rows leave the action queue.','A trial ending October 28 with a seven-day buffer has an October 21 action date. A cancellation request is still pending until confirmation is recorded.','No cancellations or reminders are sent. The action date is your planning choice, not a verified contractual deadline. Check time zones, billing cutoffs and confirmation in the provider account.',['Copy the actual trial end date from your account.','Choose a buffer after checking the service terms.','Keep a reference to the terms or confirmation.','Cancel through the provider when appropriate and mark Confirmed only with evidence.'],[['software-renewal-decision-planner','Review paid software renewals']], 'contract-renewal-workflow',['Trial ends October 28','7-day action buffer','Review October 21'],dict(window='14'))
